  "vintage_country_folk": {"parent":"functionalSong.country","axes":{"harm":0,"pitch":0,"ornament":0,"meter":0,"density":-1,"transmission":-1,"improv":0,"soundTech":-1,"intensity":-1,"voice":2,"timbre":0,"percussion":-1,"cyclicity":0},"description":"Lead singing and ringing acoustic guitar carry a ballad-oriented song. The contemporary recording setup is deliberately authored, not passed off as archival technology; the representative historic photograph documents John Grenell rather than pretending to depict Tex Morton.","exemplars":["Tex Morton","The Country Touch"],"status":"documented","crossRefs":[]},
  "scottish_folk": {"parent":"improvOnFrame.celticTraditional","axes":{"harm":0,"pitch":0,"ornament":0,"meter":1,"density":-1,"transmission":-1,"improv":0,"soundTech":-1,"intensity":-1,"voice":-2,"timbre":0,"percussion":-1,"cyclicity":0},"description":"Bowed fiddle melody and bellows-articulated accordion exchange and support dance tunes and slower airs. The selected two-player arrangement follows the actual duo; dry accordion voicing and recording details are authored choices, not a universal Scottish tuning.","exemplars":["Aly Bain and Phil Cunningham"],"status":"documented","crossRefs":[]},
